from __future__ import annotations

import gzip
import json
import logging
import os
import re
import zlib
from urllib.parse import parse_qsl, urlencode, urlsplit

import aiohttp
from aiohttp import web

LOG = logging.getLogger("legacy-glitchtip-proxy")

LEGACY_PROJECT_ID = os.environ.get("LEGACY_PROJECT_ID", "1")
LEGACY_PUBLIC_KEY = os.environ["LEGACY_PUBLIC_KEY"]
TARGET_DSN = os.environ["TARGET_DSN"]
TARGET_RELAY_URL = os.environ.get("TARGET_RELAY_URL", "http://relay:3000").rstrip("/")
LISTEN_HOST = os.environ.get("LISTEN_HOST", "0.0.0.0")
LISTEN_PORT = int(os.environ.get("LISTEN_PORT", "8001"))
MAX_BODY_SIZE = int(os.environ.get("MAX_BODY_SIZE", str(200 * 1024 * 1024)))

TARGET = urlsplit(TARGET_DSN)
TARGET_PUBLIC_KEY = TARGET.username or ""
TARGET_PROJECT_ID = TARGET.path.rstrip("/").split("/")[-1]
if not TARGET_PUBLIC_KEY or not TARGET_PROJECT_ID:
    raise RuntimeError("TARGET_DSN must contain a public key and project id")

_AUTH_KEY_RE = re.compile(r"(?:^|[,\s])sentry_key=([^,\s]+)")
_HOP_BY_HOP_HEADERS = {
    "connection",
    "keep-alive",
    "proxy-authenticate",
    "proxy-authorization",
    "te",
    "trailer",
    "transfer-encoding",
    "upgrade",
    "host",
    "content-length",
    "content-encoding",
}
_RESPONSE_HEADERS = {
    "content-type",
    "x-sentry-rate-limits",
    "retry-after",
    "access-control-allow-origin",
    "access-control-allow-headers",
    "access-control-allow-methods",
    "access-control-expose-headers",
    "cache-control",
    "vary",
}


def _dsn_public_key(dsn: str | None) -> str | None:
    if not dsn:
        return None
    try:
        return urlsplit(dsn).username
    except ValueError:
        return None


def _header_public_key(value: str | None) -> str | None:
    if not value:
        return None
    match = _AUTH_KEY_RE.search(value)
    return match.group(1) if match else None


def _decode_body(body: bytes, content_encoding: str | None) -> bytes:
    encoding = (content_encoding or "").lower().strip()
    if not encoding or encoding == "identity":
        return body
    if encoding == "gzip":
        return gzip.decompress(body)
    if encoding == "deflate":
        return zlib.decompress(body)
    if encoding == "br":
        import brotli

        return brotli.decompress(body)
    if encoding == "zstd":
        import zstandard

        return zstandard.ZstdDecompressor().decompress(body)
    raise ValueError(f"unsupported content encoding: {encoding}")


def _rewrite_store(body: bytes) -> bytes:
    try:
        event = json.loads(body)
    except (UnicodeDecodeError, json.JSONDecodeError):
        return body
    if not isinstance(event, dict):
        return body
    if "dsn" in event:
        event["dsn"] = TARGET_DSN
    return json.dumps(event, ensure_ascii=False, separators=(",", ":")).encode("utf-8")


def _rewrite_envelope(body: bytes) -> bytes:
    newline = body.find(b"\n")
    if newline < 0:
        return body
    try:
        header = json.loads(body[:newline])
    except (UnicodeDecodeError, json.JSONDecodeError):
        return body
    if not isinstance(header, dict):
        return body
    header["dsn"] = TARGET_DSN
    return json.dumps(header, ensure_ascii=False, separators=(",", ":")).encode(
        "utf-8"
    ) + body[newline:]


def _body_public_key(body: bytes, endpoint: str) -> str | None:
    if endpoint.startswith("/envelope"):
        newline = body.find(b"\n")
        if newline >= 0:
            try:
                header = json.loads(body[:newline])
                if isinstance(header, dict):
                    return _dsn_public_key(header.get("dsn"))
            except (UnicodeDecodeError, json.JSONDecodeError):
                pass
        return None
    try:
        event = json.loads(body)
    except (UnicodeDecodeError, json.JSONDecodeError):
        return None
    return _dsn_public_key(event.get("dsn")) if isinstance(event, dict) else None


def _target_path(path: str) -> tuple[str, str] | None:
    prefix = f"/api/{LEGACY_PROJECT_ID}"
    if path == "/api/store/" or path == "/api/store":
        return "/api/" + TARGET_PROJECT_ID + "/store/", "/store/"
    if path == prefix or path.startswith(prefix + "/"):
        suffix = path[len(prefix) :]
        endpoint = suffix or "/"
        return "/api/" + TARGET_PROJECT_ID + suffix, endpoint
    return None


def _target_query(query: str) -> str:
    values = [
        (key, value)
        for key, value in parse_qsl(query, keep_blank_values=True)
        if key not in {"sentry_key", "sentry_secret"}
    ]
    values.append(("sentry_key", TARGET_PUBLIC_KEY))
    return urlencode(values)


class LegacyProxy:
    def __init__(self) -> None:
        self.session: aiohttp.ClientSession | None = None

    async def start(self, _app: web.Application) -> None:
        timeout = aiohttp.ClientTimeout(total=30, connect=5, sock_read=25)
        self.session = aiohttp.ClientSession(timeout=timeout, auto_decompress=False)

    async def stop(self, _app: web.Application) -> None:
        if self.session is not None:
            await self.session.close()

    async def health(self, _request: web.Request) -> web.Response:
        return web.json_response({"ok": True, "target": "relay"})

    async def handle(self, request: web.Request) -> web.StreamResponse:
        if request.method == "OPTIONS":
            return web.Response(
                status=204,
                headers={
                    "Access-Control-Allow-Origin": "*",
                    "Access-Control-Allow-Headers": "*",
                    "Access-Control-Allow-Methods": "POST, OPTIONS",
                },
            )

        target = _target_path(request.path)
        if target is None:
            raise web.HTTPNotFound()
        target_path, endpoint = target

        if request.content_length is not None and request.content_length > MAX_BODY_SIZE:
            raise web.HTTPRequestEntityTooLarge(
                max_size=MAX_BODY_SIZE, actual_size=request.content_length
            )

        try:
            raw_body = await request.read()
            if len(raw_body) > MAX_BODY_SIZE:
                raise web.HTTPRequestEntityTooLarge(
                    max_size=MAX_BODY_SIZE, actual_size=len(raw_body)
                )
            body = _decode_body(raw_body, request.headers.get("Content-Encoding"))
        except web.HTTPException:
            raise
        except (ValueError, ImportError) as exc:
            LOG.warning("rejecting request with unusable body: %s", exc)
            raise web.HTTPUnsupportedMediaType() from exc

        supplied_key = _header_public_key(request.headers.get("X-Sentry-Auth"))
        supplied_key = supplied_key or request.rel_url.query.get("sentry_key")
        supplied_key = supplied_key or _body_public_key(body, endpoint)
        if supplied_key != LEGACY_PUBLIC_KEY:
            LOG.warning(
                "rejecting request with unexpected legacy key path=%s key_present=%s",
                request.path,
                supplied_key is not None,
            )
            raise web.HTTPForbidden()

        if endpoint.startswith("/envelope"):
            body = _rewrite_envelope(body)
            content_type = "application/x-sentry-envelope"
        elif endpoint.startswith("/store"):
            body = _rewrite_store(body)
            content_type = "application/json"
        else:
            content_type = request.headers.get("Content-Type", "application/octet-stream")

        query = _target_query(request.query_string)
        url = TARGET_RELAY_URL + target_path
        if query:
            url += "?" + query

        headers: dict[str, str] = {
            "X-Sentry-Auth": (
                f"Sentry sentry_key={TARGET_PUBLIC_KEY}, sentry_version=7, "
                "sentry_client=legacy-glitchtip-relay/1"
            ),
            "Content-Type": content_type,
        }
        for key in ("User-Agent", "Origin", "Accept", "X-Forwarded-For"):
            value = request.headers.get(key)
            if value:
                headers[key] = value
        remote = request.remote
        if remote:
            prior = headers.get("X-Forwarded-For")
            headers["X-Forwarded-For"] = f"{prior}, {remote}" if prior else remote

        assert self.session is not None
        try:
            async with self.session.request(
                request.method,
                url,
                data=body,
                headers=headers,
                allow_redirects=False,
            ) as response:
                response_body = await response.read()
                response_headers = {
                    key: value
                    for key, value in response.headers.items()
                    if key.lower() in _RESPONSE_HEADERS
                }
                return web.Response(
                    status=response.status,
                    body=response_body,
                    headers=response_headers,
                )
        except (aiohttp.ClientError, asyncio.TimeoutError) as exc:
            LOG.error("relay request failed: %s", exc)
            raise web.HTTPServiceUnavailable() from exc


proxy = LegacyProxy()
app = web.Application(client_max_size=MAX_BODY_SIZE)
app.on_startup.append(proxy.start)
app.on_cleanup.append(proxy.stop)
app.router.add_get("/healthz", proxy.health)
app.router.add_route("*", "/{path:.*}", proxy.handle)

if __name__ == "__main__":
    logging.basicConfig(
        level=os.environ.get("LOG_LEVEL", "INFO"),
        format="%(asctime)s %(levelname)s %(name)s %(message)s",
    )
    web.run_app(app, host=LISTEN_HOST, port=LISTEN_PORT)

