def _decode_body(body: bytes, content_encoding: str | None) -> bytes:
    encoding = (content_encoding or "").lower().strip()
    if not encoding or encoding == "identity":
        return body

    # aiohttp may transparently decode request bodies while retaining the
    # Content-Encoding header. Only decode when the payload still has the
    # corresponding wire-format marker; this also keeps the proxy compatible
    # with clients and server versions that leave decompression to us.
    if encoding == "gzip":
        if not body.startswith(b"\\x1f\\x8b"):
            return body
        return gzip.decompress(body)
    if encoding == "deflate":
        try:
            return zlib.decompress(body)
        except zlib.error:
            return body
    if encoding == "br":
        import brotli

        try:
            return brotli.decompress(body)
        except brotli.error:
            return body
    if encoding == "zstd":
        import zstandard

        try:
            return zstandard.ZstdDecompressor().decompress(body)
        except zstandard.ZstdError:
            return body
    raise ValueError(f"unsupported content encoding: {encoding}")

